DEFAULT_CALIBRATION = {'scale': 0.740, 'perspective': 0.169, 'depth': 0.313, 'skew': -0.034, 'x': -0.048, 'y': 0.146}



# All output sizes and padding are defined in canonical lane coordinates.
FIT_PADDING = (65, 65, 360, 500)  # left, right, top, bottom @ 2000x4000

def skin_position(item):
    settings = item.get('export', {})
    return (max(-2.0, min(2.0, float(settings.get('offset_x', 0)))),
            max(-2.0, min(2.0, float(settings.get('offset_y', 0)))))


def translate_skin(image, offset_x, offset_y):
    # Transparent clipping to the fixed 1:2 export footprint.
    dx, dy = round(image.width * offset_x), round(image.height * offset_y)
    result = Image.new('RGBA', image.size, (0, 0, 0, 0))
    result.paste(image, (dx, dy))
    return result


def skin_options(item):
    settings = item.get('export', {})
    return (settings.get('mode', 'Fit') if settings.get('mode') in ('Fit', 'Fill') else 'Fit',
            bool(settings.get('aspect', True)))


def convert_png(source, destination, mode, aspect, offset_x=0, offset_y=0):
    width, height = 2000, 4000
    with Image.open(source) as original:
        artwork = original.convert('RGBA')
    if mode == 'Fit':
        left, right, top, bottom = FIT_PADDING
        inner_w, inner_h = width - left - right, height - top - bottom
        if aspect:
            factor = min(inner_w / artwork.width, inner_h / artwork.height)
            target_w, target_h = max(1, round(artwork.width * factor)), max(1, round(artwork.height * factor))
        else:
            target_w, target_h = inner_w, inner_h
        artwork = artwork.resize((target_w, target_h), Image.Resampling.LANCZOS)
        output = Image.new('RGBA', (width, height), (0, 0, 0, 0))
        output.alpha_composite(artwork, (left + (inner_w - target_w) // 2,
                                         top + (inner_h - target_h) // 2))
    elif aspect:
        output = ImageOps.fit(artwork, (width, height), method=Image.Resampling.LANCZOS)
    else:
        output = artwork.resize((width, height), Image.Resampling.LANCZOS)
    translate_skin(output, offset_x, offset_y).save(destination, 'PNG')


def convert_webm(source, destination, mode, aspect, fps=30, offset_x=0, offset_y=0):
    ffmpeg = shutil.which('ffmpeg')
    if not ffmpeg:
        raise RuntimeError('FFmpeg is required to convert WebM skins. Install FFmpeg and add it to PATH.')
    # 1000x2000 video output, proportional to the PNG padding preset.
    if mode == 'Fit':
        if aspect:
            filt = ('scale=934:1570:force_original_aspect_ratio=decrease:flags=lanczos,'
                    'format=yuva420p,pad=934:1570:(ow-iw)/2:(oh-ih)/2:color=black@0,'
                    'pad=1000:2000:33:180:color=black@0,format=yuva420p')
        else:
            filt = ('scale=934:1570:flags=lanczos,format=yuva420p,'
                    'pad=1000:2000:33:180:color=black@0,format=yuva420p')
    elif aspect:
        filt = ('scale=1000:2000:force_original_aspect_ratio=increase:flags=lanczos,'
                'crop=1000:2000,format=yuva420p')
    else:
        filt = 'scale=1000:2000:flags=lanczos,format=yuva420p'
    # Offset after Fit/Fill, then clip against the ORIGINAL 1000x2000 lane.
    # Transparent margins remain transparent even if the image is shifted.
    dx, dy = round(1000 * offset_x), round(2000 * offset_y)
    if dx or dy:
        filt += (f',pad=3000:6000:{1000 + dx}:{2000 + dy}:color=black@0,'
                 'crop=1000:2000:1000:2000,format=yuva420p')
    # Same no-prompt FFmpeg pipeline as the supplied cg.bat:
    # 30 fps, Lanczos resizing, VP8 yuva420p, auto-alt-ref disabled.
    command = [ffmpeg, '-hide_banner', '-loglevel', 'error', '-y', '-i', str(source),
               '-map', '0:v:0', '-an', '-vf', f'fps={fps},' + filt, '-c:v', 'libvpx', '-pix_fmt', 'yuva420p',
               '-auto-alt-ref', '0', '-deadline', 'good', '-cpu-used', '3', '-b:v', '0',
               '-crf', '12', str(destination)]
    result = subprocess.run(command, capture_output=True, text=True)
    if result.returncode != 0 or not destination.is_file() or destination.stat().st_size == 0:
        raise RuntimeError('FFmpeg conversion failed: ' + (result.stderr[-1600:] or 'Unknown error'))


def read_json(path, default):
    try:
        value = json.loads(path.read_text(encoding='utf-8'))
        return value if isinstance(value, type(default)) else default
    except (OSError, ValueError):
        return default


def write_json(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + '.tmp')
    temporary.write_text(json.dumps(data, indent=2), encoding='utf-8')
    temporary.replace(path)


def drives():
    return [Path(f'{letter}:/') for letter in string.ascii_uppercase if Path(f'{letter}:/').is_dir()]


def valid_lane_folder(folder):
    try:
        p = Path(folder)
        return (p.is_dir() and p.name.lower() == 'laneskin'
                and p.parent.name.lower() == 'streamingassets'
                and p.parent.parent.name.lower() == 'legion td 2_data')
    except (OSError, ValueError):
        return False


def steam_libraries():
    roots = set()
    for drive in drives():
        for relative in ('Program Files (x86)/Steam', 'Program Files/Steam',
                         'Steam', 'Games/Steam', 'SteamLibrary'):
            root = drive / relative
            if root.is_dir():
                roots.add(root)
                vdf = root / 'steamapps' / 'libraryfolders.vdf'
                if vdf.is_file():
                    try:
                        content = vdf.read_text(encoding='utf-8-sig', errors='replace')
                        for item in re.findall(r'"path"\s+"([^"]+)"', content):
                            roots.add(Path(item.replace('\\\\', '\\')))
                    except OSError:
                        pass
    return roots


def detect_lane_folder():
    candidates = []
    for drive in drives():
        for relative in ('Games/LegionTD2', 'Games/Legion TD 2',
                         'Epic Games/LegionTD2', 'Epic Games/Legion TD 2',
                         'Program Files/Epic Games/LegionTD2',
                         'Program Files (x86)/Steam/steamapps/common/Legion TD 2',
                         'SteamLibrary/steamapps/common/Legion TD 2',
                         'Steam/steamapps/common/Legion TD 2'):
            candidates.append(drive / relative / SUFFIX)
    for root in steam_libraries():
        for name in ('Legion TD 2', 'LegionTD2'):
            candidates.append(root / 'steamapps' / 'common' / name / SUFFIX)
    for candidate in dict.fromkeys(candidates):
        if valid_lane_folder(candidate):
            return candidate
    return None


def perspective_skin(image, top_inset, depth, skew=0.0):
    """Warp a transparent RGBA skin into a trapezoid, leaving backdrop untouched."""
    if top_inset <= 0.00001 and depth <= 0.00001 and abs(skew) <= 0.00001:
        return image
    w, h = image.size
    inset = w * min(0.45, max(0.0, top_inset))
    # Output corners (trapezoid) -> source corners (full rectangle).
    # Depth is independent of narrowing: the distant edge moves downward
    # while the near/bottom edge remains anchored.
    top_y = (h - 1) * min(0.65, max(0.0, depth))
    # Shift the top edge independently, so left and right red boundaries
    # can both align without changing the overall top width.
    shift = w * min(0.4, max(-0.4, skew))
    left_top = min(w - 2, max(0, inset + shift))
    right_top = max(left_top + 1, min(w - 1, w - 1 - inset + shift))
    correspondences = [
        (left_top, top_y, 0, 0), (right_top, top_y, w - 1, 0),
        (w - 1, h - 1, w - 1, h - 1), (0, h - 1, 0, h - 1),
    ]
    equations = []
    for x, y, u, v in correspondences:
        equations.append([x, y, 1, 0, 0, 0, -u*x, -u*y, u])
        equations.append([0, 0, 0, x, y, 1, -v*x, -v*y, v])
    for col in range(8):
        pivot = max(range(col, 8), key=lambda row: abs(equations[row][col]))
        equations[col], equations[pivot] = equations[pivot], equations[col]
        div = equations[col][col]
        if abs(div) < 1e-12:
            return image
        equations[col] = [val / div for val in equations[col]]
        for row in range(8):
            if row != col:
                factor = equations[row][col]
                equations[row] = [a - factor*b for a, b in zip(equations[row], equations[col])]
    coefficients = [row[8] for row in equations]
    return image.transform((w, h), Image.Transform.PERSPECTIVE, coefficients,
                           resample=Image.Resampling.BICUBIC, fillcolor=(0, 0, 0, 0))


class LaneEditor(tk.Tk):
    def __init__(self):
        super().__init__()
        APP_DIR.mkdir(parents=True, exist_ok=True)
        LIBRARY_DIR.mkdir(parents=True, exist_ok=True)
        BACKGROUND_DIR.mkdir(parents=True, exist_ok=True)
        self.config_data = read_json(CONFIG_FILE, {})
        # Seed calibration defaults once. Changes are only persisted by Save Calibration.
        if not isinstance(self.config_data.get('preview_calibration'), dict):
            self.config_data['preview_calibration'] = dict(DEFAULT_CALIBRATION)
            write_json(CONFIG_FILE, self.config_data)
        self.debug_visible = tk.BooleanVar(value=False)
        self.calibration = dict(DEFAULT_CALIBRATION)
        self.calibration.update({k: v for k, v in self.config_data['preview_calibration'].items()
                                 if k in DEFAULT_CALIBRATION and isinstance(v, (int, float))})
        # Migrate the old combined slider to separate width/depth values.
        if 'depth' not in self.config_data['preview_calibration']:
            self.calibration['depth'] = min(0.65, max(0.0, self.calibration['perspective']) * 1.4)
        self.cal_vars = {k: tk.DoubleVar(value=self.calibration[k]) for k in DEFAULT_CALIBRATION}
        self._default_background = Image.open(BytesIO(base64.b64decode(''.join(DEFAULT_BACKGROUND_PNG)))).convert('RGBA')
        self.library = read_json(LIBRARY_FILE, [])
        self.backgrounds = read_json(BACKGROUND_FILE, [])
        self.background_choice = tk.StringVar(value='Default (built-in)')
        self.preview_mode = tk.StringVar(value='Fit')
        self.keep_aspect = tk.BooleanVar(value=True)
        self.skin_offset_x = tk.DoubleVar(value=0)
        self.skin_offset_y = tk.DoubleVar(value=0)
        self.grid_overlay_path = GRID_OVERLAY_FILE
        self._grid_image = self.load_grid_overlay()
        self.walls_image = self.load_walls_overlay()
        self.walls_visible = tk.BooleanVar(value=bool(self.config_data.get('walls_visible', False)))
        self.grid_visible = tk.BooleanVar(value=False)
        self.grid_opacity = tk.DoubleVar(value=float(self.config_data.get('grid_opacity', 100)))
        self.grid_calibration = dict(self.config_data.get('grid_calibration', {
            'scale': 1.0, 'x': 0.0, 'y': 0.0,
            'perspective': 0.0, 'depth': 0.0, 'skew': 0.0
        }))
        self.grid_vars = {key: tk.DoubleVar(value=self.grid_calibration[key])
                          for key in ('scale', 'x', 'y', 'perspective', 'depth', 'skew')}
        self.skin_opacity = tk.DoubleVar(value=100)  # preview-only, never saved
        self._loading_skin_settings = False
        self.background_choices = []
        self.preview_source = None
        self.preview_zoom = 1.0  # View-only zoom, independent of saved calibration/export.
        self.preview_pan_x = 0
        self.preview_pan_y = 0
        self._preview_drag_start = None
        self.animation_frames = []
        self.animation_durations = []
        self.animation_index = 0
        self.animation_job = None
        self.animation_generation = 0
        self.animation_queue = queue.Queue()
        self.animation_playing = True
        self.preview_message = 'Select a saved skin'
        self._preview_job = None
        self.game_path = tk.StringVar()
        self.status = tk.StringVar(value='Ready')
        self.build_choice = tk.StringVar(value='None (default game lane)')
        self.battle_choice = tk.StringVar(value='None (use build skin)')
        # FPS controls apply to installation, not the preview or imported originals.
        self.build_fps = tk.StringVar(value=str(self.config_data.get('build_fps', 30)))
        self.battle_fps = tk.StringVar(value=str(self.config_data.get('battle_fps', 30)))
        self._fps_warned = {'build': None, 'battle': None}
        self.skin_choices = []
        self.selected_id = None
        self.preview_image = None
        self.title(APP_NAME)
        self.geometry(self.initial_geometry())
        self.minsize(760, 600)
        self.build_ui()
        self.refresh_library()
        self.refresh_background_choices()
        self.after(150, self.initialize_location)
        self.protocol('WM_DELETE_WINDOW', self.on_close)

    def initial_geometry(self):
        # Respect Windows taskbar/short screens while giving the Apply controls room.
        screen_w = self.winfo_screenwidth()
        screen_h = self.winfo_screenheight()
        width = min(1120, max(760, screen_w - 100))
        height = min(930, max(600, screen_h - 130))
        x = max(0, (screen_w - width) // 2)
        y = max(0, (screen_h - height) // 2 - 20)
        return f'{width}x{height}+{x}+{y}'

    def open_appdata_folder(self):
        try:
            APP_DIR.mkdir(parents=True, exist_ok=True)
            os.startfile(str(APP_DIR))
        except (OSError, AttributeError) as exc:
            messagebox.showerror('Open AppData Folder', f'Could not open {APP_DIR}\n\n{exc}')

    def build_ui(self):
        main = ttk.Frame(self, padding=10)
        main.pack(fill='both', expand=True)
        header = ttk.Frame(main)
        header.pack(fill='x', pady=(0, 6))
        ttk.Label(header, text=APP_NAME, font=('Segoe UI', 15, 'bold')).pack(side='left')
        ttk.Checkbutton(header, text='Debug', variable=self.debug_visible,
                        command=self.toggle_debug).pack(side='right')
        ttk.Button(header, text='Open AppData Folder', command=self.open_appdata_folder).pack(side='right', padx=(0, 12))
        location = ttk.LabelFrame(main, text='Game Location', padding=6)
        location.pack(fill='x')
        location.columnconfigure(0, weight=1)
        ttk.Entry(location, textvariable=self.game_path, state='readonly').grid(row=0, column=0, sticky='ew', padx=(0, 8))
        ttk.Button(location, text='Select', command=self.select_folder).grid(row=0, column=1, padx=(0, 6))
        ttk.Button(location, text='Auto Detect', command=self.auto_detect).grid(row=0, column=2)

        notebook = ttk.Notebook(main)
        notebook.pack(fill='both', expand=True, pady=(7, 5))
        library_tab = ttk.Frame(notebook, padding=7)
        notebook.add(library_tab, text='Skin Library / Load')
        library_tab.columnconfigure(1, weight=1)
        library_tab.rowconfigure(1, weight=1)

        controls = ttk.Frame(library_tab)
        controls.grid(row=0, column=0, columnspan=2, sticky='ew', pady=(0, 5))
        ttk.Button(controls, text='Import PNG / WEBM / GIF', command=self.import_skin).pack(side='left', padx=(0, 8))
        ttk.Button(controls, text='Rename', command=self.rename_skin).pack(side='left', padx=(0, 8))
        ttk.Button(controls, text='Delete from Library', command=self.delete_skin).pack(side='left')

        left = ttk.LabelFrame(library_tab, text='Saved Skins', padding=8)
        left.grid(row=1, column=0, sticky='ns', padx=(0, 12))
        self.skin_list = tk.Listbox(left, width=34, exportselection=False)
        self.skin_list.pack(side='left', fill='both', expand=True)
        scrollbar = ttk.Scrollbar(left, orient='vertical', command=self.skin_list.yview)
        scrollbar.pack(side='right', fill='y')
        self.skin_list.configure(yscrollcommand=scrollbar.set)
        self.skin_list.bind('<<ListboxSelect>>', self.on_skin_selected)

        right = ttk.LabelFrame(library_tab, text='Preview', padding=6)
        right.grid(row=1, column=1, sticky='nsew')
        right.columnconfigure(0, weight=1)
        right.rowconfigure(2, weight=1)
        bgbar = ttk.Frame(right)
        bgbar.grid(row=0, column=0, sticky='ew', pady=(0, 4))
        ttk.Label(bgbar, text='Background:').pack(side='left', padx=(0, 6))
        self.background_combo = ttk.Combobox(bgbar, textvariable=self.background_choice,
                                             state='readonly', width=23)
