        self.background_combo.bind('<<ComboboxSelected>>', self.on_background_changed)
        ttk.Button(bgbar, text='Add...', command=self.import_background).pack(side='left', padx=(0, 4))
        ttk.Button(bgbar, text='Remove', command=self.remove_background).pack(side='left', padx=(0, 8))
        ttk.Label(bgbar, text='View:').pack(side='left', padx=(0, 4))
